const fs=require('fs'),zlib=require('zlib');
function readPNG(f){
 const b=fs.readFileSync(f); let off=8; const chunks=[]; let w,h,bd,ct,idat=[];
 while(off<b.length){const len=b.readUInt32BE(off);const type=b.toString('ascii',off+4,off+8);const data=b.slice(off+8,off+8+len);
  if(type==='IHDR'){w=data.readUInt32BE(0);h=data.readUInt32BE(4);bd=data[8];ct=data[9];}
  if(type==='IDAT')idat.push(data);
  if(type==='IEND')break; off+=12+len;}
 const raw=zlib.inflateSync(Buffer.concat(idat));
 const ch=ct===6?4:ct===2?3:1; const stride=w*ch;
 const out=Buffer.alloc(w*h*ch);
 let pos=0;
 for(let y=0;y<h;y++){const ft=raw[pos++];const line=raw.slice(pos,pos+stride);pos+=stride;
  const prev=y>0?out.slice((y-1)*stride,y*stride):Buffer.alloc(stride);
  const cur=Buffer.alloc(stride);
  for(let x=0;x<stride;x++){const a=x>=ch?cur[x-ch]:0;const bb=prev[x];const c=x>=ch?prev[x-ch]:0;let v=line[x];
   switch(ft){case 0:break;case 1:v+=a;break;case 2:v+=bb;break;case 3:v+=(a+bb)>>1;break;case 4:{const p=a+bb-c;const pa=Math.abs(p-a),pb=Math.abs(p-bb),pc=Math.abs(p-c);v+= (pa<=pb&&pa<=pc)?a:(pb<=pc?bb:c);break;}}
   cur[x]=v&255;}
  cur.copy(out,y*stride);}
 return {w,h,ch,data:out};
}
// crop region from tile-6: right part of issues header row. tile-6 y offset 2880 in shot; header row in tile-6 around y=200-220
const img=readPNG('tile-6.png');
function crop(x0,y0,x1,y1,scale){const W=(x1-x0)*scale,H=(y1-y0)*scale;const o=Buffer.alloc(W*H*3);
 for(let y=0;y<H;y++)for(let x=0;x<W;x++){const sx=x0+Math.floor(x/scale),sy=y0+Math.floor(y/scale);const i=(sy*img.w+sx)*img.ch;const j=(y*W+x)*3;o[j]=img.data[i];o[j+1]=img.data[i+1];o[j+2]=img.data[i+2];}
 return {W,H,o};}
const c=crop(1000,180,1248,260,4);
// write PNG
function crc32(buf){let c,t=[];for(let n=0;n<256;n++){c=n;for(let k=0;k<8;k++)c=c&1?0xedb88320^(c>>>1):c>>>1;t[n]=c>>>0;}let crc=0xffffffff;for(const b of buf)crc=t[(crc^b)&255]^(crc>>>8);return (crc^0xffffffff)>>>0;}
function chunk(type,data){const len=Buffer.alloc(4);len.writeUInt32BE(data.length);const td=Buffer.concat([Buffer.from(type),data]);const crc=Buffer.alloc(4);crc.writeUInt32BE(crc32(td));return Buffer.concat([len,td,crc]);}
const ihdr=Buffer.alloc(13);ihdr.writeUInt32BE(c.W,0);ihdr.writeUInt32BE(c.H,4);ihdr[8]=8;ihdr[9]=2;
const rows=[];for(let y=0;y<c.H;y++){rows.push(Buffer.from([0]));rows.push(c.o.slice(y*c.W*3,(y+1)*c.W*3));}
fs.writeFileSync('crop.png',Buffer.concat([Buffer.from([137,80,78,71,13,10,26,10]),chunk('IHDR',ihdr),chunk('IDAT',zlib.deflateSync(Buffer.concat(rows))),chunk('IEND',Buffer.alloc(0))]));
console.log('ok');
"
